Copy the workbook, read the selected date in Overview!A2 and the Pay Dates table from cached values. Sum Paycheck 1 and Paycheck 2 for all rows whose date has the same year and month as A2. Write the resulting total as a plain value into Overview!B5.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

overview_vals = vals["Overview"]
pay_dates_vals = vals["Pay Dates"]

def to_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            return (datetime(1899, 12, 30) + timedelta(days=float(value))).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        formats = (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%d-%b-%Y",
            "%B %d, %Y",
            "%B %d",
        )
        for fmt in formats:
            try:
                return datetime.strptime(s, fmt).date()
            except Exception:
                pass
        try:
            import pandas as pd
            return pd.to_datetime(s).date()
        except Exception:
            return None
    return None

def to_number(value):
    if isinstance(value, bool):
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except Exception:
            return 0.0
    return 0.0

selected = to_date(overview_vals["A2"].value)
total = 0.0
matched_rows = 0

if selected is not None:
    for row in range(2, pay_dates_vals.max_row + 1):
        d = to_date(pay_dates_vals.cell(row=row, column=1).value)
        if d is not None and d.year == selected.year and d.month == selected.month:
            pay1 = to_number(pay_dates_vals.cell(row=row, column=2).value)
            pay2 = to_number(pay_dates_vals.cell(row=row, column=3).value)
            if pay1 or pay2:
                total += pay1 + pay2
                matched_rows += 1

answer_ws = wb["Overview"]
answer_ws["B5"] = int(total) if float(total).is_integer() else round(total, 2)

print("selected date:", selected)
print("matched rows:", matched_rows)
print("B5 value:", answer_ws["B5"].value)

wb.save(OUT)
